INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(5501, 'Joshua 6:4', 'Joshua', 6, 4, '&nbsp;اووۀ اِمامان به د لوظ صندوق نه مخکښې روان شى چې د هر يو سره به يو يو بيګل وى. نو په اوومه ورځ به تۀ او ستا سپاهيان د ښار نه ګېرچاپېره اووۀ چکرې لګوئ او اِمامان بيګلى غږوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5502, 'Joshua 6:5', 'Joshua', 6, 5, '&nbsp;بيا دې هغوئ په يو اوږد آواز سره بيګل وغږوى. او څنګه چې تاسو دا آواز واورئ نو ټول خلق دې د اوچت آواز سره يو نعره ووهى نو د ښار دېوالونه به راوغورزيږى او بيا به ستاسو ټول لښکر سيدها ښار ته ورننوځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5503, 'Joshua 6:6', 'Joshua', 6, 6, '&nbsp;نو يشوَع د نون زوئ اِمامان راوغوښتل او ورته يې وفرمائيل، ”د لوظ صندوق واخلئ او په تاسو کښې دې اووۀ اِمامان د بيګلو سره مخکښې روان شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5504, 'Joshua 6:7', 'Joshua', 6, 7, '&nbsp;بيا هغۀ خلقو ته حُکم ورکړو چې، ”د ښار نه ګېرچاپېره مزل شروع کړئ او وسله بند سړى دې د مالِک خُدائ د لوظ صندوق نه مخکښې روان وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5505, 'Joshua 6:10', 'Joshua', 6, 10, '&nbsp;خو يشوَع خلقو له حُکم ورکړو چې، ”چغې مۀ وهئ او چې تر کومې ورځې پورې ما حُکم نۀ وى درکړے نو د خولې نه يوه خبره هم مۀ وباسئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5506, 'Joshua 6:11', 'Joshua', 6, 11, '&nbsp;هغۀ دې کسانو ته وفرمائيل چې، ”د مالِک خُدائ د لوظ صندوق يو ځل د ښار نه ګېرچاپېره وګرځوئ.“ بيا هغوئ کېمپ ته واپس راغلل او شپه يې هلته تېره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5507, 'Joshua 6:14', 'Joshua', 6, 14, '&nbsp;نو په دوېمه ورځ هغوئ د ښار نه ګېرچاپېره يو ځل بيا چکر ولګولو او بيا کېمپ ته واپس راغلل. هغوئ شپږ ورځې داسې کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5508, 'Joshua 6:15', 'Joshua', 6, 15, '&nbsp;په اوومه ورځ سحر وختى چې رڼا شروع کېده نو هغوئ پاڅېدل او په دغه ورځ يې د ښار نه ګېرچاپېره اووۀ چکرې ولګولې. صِرف په دې ورځ هغوئ ګېرچاپېره اووۀ چکرې ولګولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5509, 'Joshua 6:16', 'Joshua', 6, 16, '&nbsp;په اوؤم چکر باندې چې کله اِمامانو بيګلې وغږولې نو يشوَع خلقو له حُکم ورکړو، ”چغې ووهئ ځکه چې مالِک خُدائ دا ښار تاسو له درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5510, 'Joshua 6:17', 'Joshua', 6, 17, '&nbsp;دا ښار او په دې کښې هر څۀ به مالِک خُدائ ته د نذرانې په توګه د تباه کولو دپاره پېش کړے شى. صِرف راحب کنجره او د هغې خاندان به بچ کړے شى ځکه چې هغې زمونږ جاسوسانو له پناه ورکړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5511, 'Joshua 6:18', 'Joshua', 6, 18, '&nbsp;کوم څيزونه چې تباه کولے شى د هغې نه به تاسو هيڅ هم نۀ اخلئ، کۀ چرې تاسو داسې وکړئ نو تاسو به د بنى اِسرائيلو په کېمپ باندې تکليف او تباهى راولئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5512, 'Joshua 6:19', 'Joshua', 6, 19, '&nbsp;هر څۀ چې د سپينو زرو، سرو زرو، زېړو يا د اوسپنې نه جوړ وى هغه به مالِک خُدائ ته وقف کړے شى. او هغه به د مالِک خُدائ په خزانه کښې کېښودے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5513, 'Joshua 6:20', 'Joshua', 6, 20, '&nbsp;او اِمامانو بيګلې وغږولې او چې څنګه خلقو د دې آواز واورېدو نو هغوئ يوه اوچته نعره ووهله او دېوالونه راوغورزېدل. بيا ټول لښکر سيدها ښار ته ننوتلو او قبضه يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5514, 'Joshua 6:21', 'Joshua', 6, 21, '&nbsp;هغوئ په ښار کښې هر يو کس، سړى او ښځې، ځوانان او بوډاګان په خپلو تُورو باندې ووژل. هغوئ څاروى، ګډې او خرونه هم ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5515, 'Joshua 6:22', 'Joshua', 6, 22, '&nbsp;خو يشوَع هغه دوو کسانو ته وفرمائيل چا چې جاسوسى کړې وه، ”د هغه کنجرې کور ته لاړ شئ او څنګه چې تاسو د هغې سره وعده کړې ده هغه او د هغې خاندان راولئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5516, 'Joshua 6:23', 'Joshua', 6, 23, '&nbsp;نو هغوئ لاړل او راحب يې سره د هغې د مور او پلار، وروڼو او خوېندو او باقى خاندان سره رابهر کړه. هغوئ هغه ټول خاندان او نوکران محفوظ ځائ ته بوتلل چې د بنى اِسرائيلو کېمپ سره نزدې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5517, 'Joshua 6:24', 'Joshua', 6, 24, '&nbsp;بيا هغوئ ښار او په هغې کښې هر څۀ وسوزول، خو صِرف سرۀ زر، سپين زر، زېړ او اوسپنه هغوئ پرېښودل او د مالِک خُدائ په خزانه کښې يې کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5518, 'Joshua 6:25', 'Joshua', 6, 25, '&nbsp;خو يشوَع د راحب کنجرې او د هغې د ټولو خپلوانو ژوند بچ کړو، ځکه چې هغۀ کوم جاسوسان يريحو ته لېږلى وُو هغوئ له يې پناه ورکړې وه. د هغې اولاد تر اوسه پورې د بنى اِسرائيلو سره اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5519, 'Joshua 6:26', 'Joshua', 6, 26, '&nbsp;په هغه وخت يشوَع سختې ښېرې وکړې چې، ”څوک هم د يريحو د ښار د دوباره جوړولو کوشش کوى نو د مالِک خُدائ غضب دې ورباندې وى. څوک هم چې د دې بنياد کېږدى نو هغه دې د مشرى زوئ نه لاس ووينځى. څوک هم چې د دې دروازې جوړوى نو هغه دې د کشر زوئ نه لاس ووينځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5520, 'Joshua 6:27', 'Joshua', 6, 27, '&nbsp;نو مالِک خُدائ د يشوَع مل وو او هغه په ټول مُلک کښې مشهور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5521, 'Joshua 7:1', 'Joshua', 7, 1, '&nbsp;خو بنى اِسرائيلو مالِک خُدائ ته د تباه کېدونکو څيزونو سره خيانت وکړو. عکن نومې سړى د دې حُکم نافرمانى وکړه نو مالِک خُدائ بنى اِسرائيلو ته سخت غصه شو. عکن د کرمى زوئ او د زبدى نمسے وو د زارح د خاندان سره يې تعلق لرلو او دا د يهوداه د قبيلې يوه حِصه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5522, 'Joshua 7:2', 'Joshua', 7, 2, '&nbsp;يشوَع څۀ سړى د يريحو نه د دې حُکم سره ولېږل چې د عى ښار جاسوسى وکړى. د عى ښار د بيت‌ايل نمرخاتۀ په طرف او د بيت‌آون سره نزدې وو. نو سړى لاړل او جاسوسى يې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5523, 'Joshua 7:3', 'Joshua', 7, 3, '&nbsp;او کله چې هغوئ راواپس شول نو يشوَع له يې خبر ورکړو چې، ”د ټولو خلقو په عى باندې د حملې کولو ضرورت نشته. صِرف دوه درې زره سړى ولېږه. ټول لښکر مۀ ستړے کوه ځکه چې هغه دومره لوئ ښار نۀ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5524, 'Joshua 7:4', 'Joshua', 7, 4, '&nbsp;نو تقريباً درې زره اِسرائيلو په هغوئ باندې حمله وکړله خو د عى ښار د خلقو نه راوتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5525, 'Joshua 7:5', 'Joshua', 7, 5, '&nbsp;د عى سړى د ښار د دروازې نه په هغوئ پسې شول او د کانونو پورې ورپسې لاړل او د غونډۍ په لاره باندې يې ترې نه تقريباً شپږ دېرش کسان ووژل. نو بنى اِسرائيلو حوصله بائيله او ويرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5526, 'Joshua 7:6', 'Joshua', 7, 6, '&nbsp;يشوَع او د بنى اِسرائيلو مشرانو د غمه جامې وشلولې او د مالِک خُدائ د لوظ صندوق په مخکښې يې ځانونه په زمکه باندې پړمخې راوغورزول او تر ماښامه پورې هلته پراتۀ وُو، د هغوئ په سرونو کښې خاورې وې چې د هغوئ خفګان ترې نه څرګندېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5527, 'Joshua 7:7', 'Joshua', 7, 7, '&nbsp;او يشوَع وفرمائيل، ”اے مالِکه خُدايه، تا ولې مونږ د اُردن نه راپورې وويستلو؟ د دې دپاره چې مونږ اموريانو ته حواله کړې؟ چې مونږ تباه کړې؟ مونږ د اُردن په بله غاړه باندې ولې ايسار نۀ شُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5528, 'Joshua 7:8', 'Joshua', 7, 8, '&nbsp;اے مالِکه خُدايه، اوس چې بنى اِسرائيل د دشمنانو نه په شا شوى دى نو زۀ څۀ ووايم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5529, 'Joshua 7:9', 'Joshua', 7, 9, '&nbsp;کنعانيان او د مُلک نور خلق به د دې نه خبر شى. هغوئ به مونږ راګېر کړى او زمونږ نوم به د زمکې د مخ نه ختم کړى. بيا به تۀ د خپل عزتمند نوم د بچ کولو دپاره څۀ کوې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5530, 'Joshua 7:10', 'Joshua', 7, 10, '&nbsp;مالِک خُدائ يشوَع ته وفرمائيل، ”ودرېږه. تۀ ولې داسې پړمخې پروت يې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5531, 'Joshua 7:11', 'Joshua', 7, 11, '&nbsp;بنى اِسرائيلو ګناه کړې ده. هغوئ زما سره هغه لوظ مات کړے دے چې ما ورته حُکم کړے وو چې دوئ به يې نۀ ماتوى. هغوئ د هغه څيزونو نه څۀ اخستى دى چې کوم وقف کولے شول. هغوئ هغه پټ کړل، د هغې په حقله يې دروغ ووئيل او د خپل سامان سره يې کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5532, 'Joshua 7:12', 'Joshua', 7, 12, '&nbsp;نو په دې وجه بنى اِسرائيل د خپلو دشمنانو مقابله نۀ شى کولے. هغوئ د خپلو دشمنانو نه په شا شول ځکه چې هغوئ په خپله اوس د تباهۍ حقدار دى. زۀ به تر هغې پورې نور ستاسو مل نۀ يم چې تاسو هغه وقف شوى څيزونه تباه کړى نۀ وى چې کوم تاسو سره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5533, 'Joshua 7:13', 'Joshua', 7, 13, '&nbsp;پاڅه. خلق زما حضور ته راتلو دپاره پاک او تيار کړه. هغوئ ته ووايه چې سبا تيار اوسئ ځکه چې زۀ مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې وايم چې، بنى اِسرائيلو، تاسو سره وقف شوى څيزونه دى. تاسو تر هغې پورې د خپلو دشمنانو مقابله نۀ شئ کولے چې دا څيزونه مو لرې کړى نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5534, 'Joshua 7:14', 'Joshua', 7, 14, '&nbsp;هغوئ ته ووايه چې په سحر کښې به هغوئ قبيله په قبيله بهر مخې ته راوستے شى. او کومه قبيله چې زۀ په نښه کړم هغه به قبيله په قبيله مخې ته راوستے شى. او کومه قبيله چې زۀ په نښه کړم هغوئ به خاندان په خاندان مخې ته راوستے شى. او کوم خاندان چې زۀ په نښه کړم هغوئ کښې به يو په يو مخې ته راوستے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5535, 'Joshua 7:15', 'Joshua', 7, 15, '&nbsp;څوک چې په نښه کړے شو او حرام څيزونه ورسره پېدا شول نو هغه به په اور باندې د خپل خاندان او د خپل هر څيز سره سوزولے شى. ځکه چې هغوئ بنى اِسرائيل سخت شرمولى دى او زما لوظ يې مات کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5536, 'Joshua 7:16', 'Joshua', 7, 16, '&nbsp;په ورپسې سحر وختى يشوَع بنى اِسرائيل قبيله په قبيله مخکښې راوستل او د يهوداه قبيله په نښه کړے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5537, 'Joshua 7:17', 'Joshua', 7, 17, '&nbsp;هغۀ د يهوداه قبيله خاندان په خاندان مخکښې راوستل او د زارح قبيله په نښه کړے شوه. بيا هغۀ د زارح قبيله خاندان په خاندان مخکښې راوسته او د زبدى قبيله په نښه کړے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5538, 'Joshua 7:18', 'Joshua', 7, 18, '&nbsp;بيا هغۀ د زبدى د خاندان نه يو په يو مخکښې راوستو او عکن د کرمى زوئ او د زبدى نمسے په نښه کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5539, 'Joshua 7:19', 'Joshua', 7, 19, '&nbsp;يشوَع هغۀ ته وفرمائيل، ”زما زويه، د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک په وړاندې اِقرار وکړه او رښتيا ووايه. اوس ما ته ووايه چې تا څۀ کړى دى. زما نه د پټولو کوشش مۀ کوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5540, 'Joshua 7:20', 'Joshua', 7, 20, '&nbsp;عکن جواب ورکړو، ”دا رښتيا دى چې ما د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک خِلاف ګناه کړې ده او دا کار مې کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5541, 'Joshua 7:21', 'Joshua', 7, 21, '&nbsp;په هغه څيزونو کښې چې مونږ لوټ کړى وُو ما په کښې يوه ښائسته بابلى چُوغه او تقريباً دوه کلو سپين زر او نيم کلو نه زياته د سرو زرو خښته وليده. هغه زما ډېر زيات خوښ شول نو ما واخستل. تۀ به وګورې چې هغه زما په خېمه کښې ښخ دى او په بېخ کښې يې سپين زر دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5542, 'Joshua 7:22', 'Joshua', 7, 22, '&nbsp;نو يشوَع څۀ سړى هلته ولېږل، هغوئ خېمې ته ورمنډه کړه او ګورئ چې هغه څيزونه يې هلته وموندل چې ښخ وُو او په بېخ کښې يې سپين زر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5543, 'Joshua 7:23', 'Joshua', 7, 23, '&nbsp;او هغوئ هغه د خېمې نه بهر راوويستل او يشوَع او ټولو بنى اِسرائيلو له يې راوړل او د مالِک خُدائ په حضور کښې يې کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5544, 'Joshua 7:24', 'Joshua', 7, 24, '&nbsp;يشوَع او د بنى اِسرائيلو ټول قوم عکن، د هغۀ زامن او لوڼه، سپين زر، چُوغه، د سرو زرو ښخته په قبضه کښې واخستل او سره د دې، د هغۀ څاروى، خرونه، ګډې، خېمه او د دې نه علاوه هر څۀ چې هغۀ لرل هغوئ واخستل او د مصيبت وادۍ ته يې يوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5545, 'Joshua 7:25', 'Joshua', 7, 25, '&nbsp;او يشوَع وفرمائيل، ”تا ولې په مونږ داسې سخت تکليف راوستے دے؟ اوس به مالِک خُدائ په تا تکليف راولى.“ بيا ټولو خلقو عکن سنګسار کړو او مړ شو. هغوئ د هغۀ خاندان سنګسار کړل او هغوئ يې سره د هر څۀ وسوزل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5546, 'Joshua 7:26', 'Joshua', 7, 26, '&nbsp;هغوئ د هغۀ دپاسه د کاڼو يو غټ ډېرے جوړ کړو کوم چې تر نن ورځې پورې هلته دے. نو د مالِک خُدائ غصه سړه شوه او په دې وجه دغه ځائ ته تر اوسه پورې د مصيبت وادى وئيلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5547, 'Joshua 8:1', 'Joshua', 8, 1, '&nbsp;مالِک خُدائ يشوَع ته وفرمائيل، ”يرېږه مه او مۀ بې‌حوصلې کېږه. ټول لښکر ځان سره کړه او عى ته لاړ شه. زۀ به د عى په بادشاه، د هغۀ په خلقو او په ښار تا له فتح درکړم او هغه مُلک به ستا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5548, 'Joshua 8:2', 'Joshua', 8, 2, '&nbsp;تاسو به عى او د هغې د بادشاه سره هغه څۀ کوئ کوم چې تاسو د يريحو او د هغې بادشاه سره کړى وُو. خو دا ځل تاسو د هغوئ لوټ شوے مال او ځناور په خپل استعمال کښې راوستلے شئ. د ښار شا ته د هغوئ خِلاف حملې کولو دپاره په پټ ځائ کښې کښېنئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5549, 'Joshua 8:3', 'Joshua', 8, 3, '&nbsp;نو يشوَع د خپلو ټولو سپاهيانو سره تيار شو چې عى ته لاړ شى. هغۀ د خپل لښکر دېرش زره د ټولو نه ښۀ سپاهيان خوښ کړل او هغوئ يې د شپې ولېږل', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5550, 'Joshua 8:4', 'Joshua', 8, 4, '&nbsp;او دا حُکم يې ورکړو، ”د ښار بل طرف ته پټ شئ خو ډېر لرې مۀ ځئ او حملې کولو ته تيار شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5551, 'Joshua 8:5', 'Joshua', 8, 5, '&nbsp;زۀ او زما سړى به ښار ته نزدې ورشُو. کله چې د عى خلق زمونږ خِلاف راوځى نو مونږ به واپس رامنډه کړُو بلکل هم هغسې لکه چې مونږه په اول ځل کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5552, 'Joshua 8:6', 'Joshua', 8, 6, '&nbsp;هغوئ به په مونږ پسې وى او د ښار نه به يې لرې بوځُو. هغوئ به داسې خيال کوى چې د مخکښې په شان مونږ د هغوئ نه تښتُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5553, 'Joshua 8:7', 'Joshua', 8, 7, '&nbsp;بيا به تاسو راوځئ او په ښار به قبضه وکړئ. نو مالِک خُدائ ستاسو خُدائ پاک به دا تاسو له درکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5554, 'Joshua 8:8', 'Joshua', 8, 8, '&nbsp;چې هغه ښار قبضه کړئ نو وې سوزوئ، هم هغسې چې څنګه مالِک خُدائ حُکم کړے دے. ګورئ ما دا حُکمونه درکړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5555, 'Joshua 8:9', 'Joshua', 8, 9, '&nbsp;نو يشوَع هغوئ ولېږل او هغوئ خپل پټ ځائ ته لاړل چې د عى نمرپرېواتۀ طرف ته، د عى او بيت‌ايل په مينځ کښې دے. يشوَع په کېمپ کښې د خلقو په مينځ کښې شپه تېره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5556, 'Joshua 8:10', 'Joshua', 8, 10, '&nbsp;يشوَع سحر وختى پاڅېدو او سپاهيان يې يو ځائ ته راغونډ کړل. بيا هغۀ او د بنى اِسرائيلو مشرانو هغوئ عى ته بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5557, 'Joshua 8:11', 'Joshua', 8, 11, '&nbsp;سپاهيان د هغۀ سره د ښار د غټې دروازې طرف ته لاړل او هلته يې د شمال طرف ته خېمې ودرولې، او هلته د دوئ او عى تر مينځه يوه وادى وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5558, 'Joshua 8:12', 'Joshua', 8, 12, '&nbsp;هغۀ تقريباً پينځۀ زره سړى د ځان سره کړل او د ښار نمرپرېواتۀ ته يې پټو ځايونو ته بوتلل چې د عى او د بيت‌ايل تر مينځه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5559, 'Joshua 8:13', 'Joshua', 8, 13, '&nbsp;نو هغوئ زيات لښکر د ښار شمالى طرف ته او پټ شوى سړى د ښار نمرپرېواتۀ طرف ته د جنګ دپاره تيار کړل. يشوَع شپه په وادۍ کښې تېره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5560, 'Joshua 8:14', 'Joshua', 8, 14, '&nbsp;کله چې د عى بادشاه د يشوَع سړى وليدل نو هغه په تېزۍ سره راووتلو. هغه او د هغۀ ټول سړى د اُردن د وادۍ په طرف د بنى اِسرائيلو سره د جنګ کولو دپاره هغه مخکښېنى ځائ ته لاړل. او دا پته ورته نۀ وه چې د شا د طرف نه ورباندې حمله کېدونکې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5561, 'Joshua 8:15', 'Joshua', 8, 15, '&nbsp;يشوَع او د هغۀ سړو داسې ښکاره کړه چې په شا کيږى او د صحرا طرف ته تښتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5562, 'Joshua 8:16', 'Joshua', 8, 16, '&nbsp;د ښار ټول سړى راغونډ کړے شوى وُو چې هغوئ پسې شى او چې څومره هغوئ يشوَع پسې تلل نو د ښار نه نور هم لرې کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5563, 'Joshua 8:17', 'Joshua', 8, 17, '&nbsp;په عى او بيت‌ايل کښې داسې يو سړے هم پاتې نۀ شو چې هغه بنى اِسرائيلو پسې نۀ وو تلے. هغوئ ښار کولاو پرېښودو او په بنى اِسرائيلو پسې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5564, 'Joshua 8:18', 'Joshua', 8, 18, '&nbsp;بيا مالِک خُدائ يشوَع ته وفرمائيل، ”خپله نېزه د عى طرف ته کړه، زۀ دا ښار تا له درکوم.“ يشوَع ته چې څنګه ووئيلے شول نو هغسې يې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5565, 'Joshua 8:19', 'Joshua', 8, 19, '&nbsp;او څنګه چې هغۀ لاس اوچت کړو نو هغه سړى چې پټ شوى وُو زر پاڅېدل، ښار ته يې ورمنډه کړه، ورننوتل او قبضه يې کړو. هغوئ سمدستى په ښار اور ولګولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5566, 'Joshua 8:20', 'Joshua', 8, 20, '&nbsp;کله چې د عى سړو شاته وکتل نو هغوئ وليدل چې لوګے د آسمان طرف ته ختو. هغوئ ته د تښتېدلو دپاره لار پاتې نۀ شوه ځکه چې کومو بنى اِسرائيلو چې د صحرا طرف ته منډه وهله نو هغوئ ورباندې د حملې کولو دپاره راواپس شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5567, 'Joshua 8:21', 'Joshua', 8, 21, '&nbsp;کله چې يشوَع او ټولو بنى اِسرائيلو ته پته ولګېده چې پټو شوو سړو ښار قبضه کړے دے او اور يې لګولے دے نو هغوئ راواپس شول او د عى سړى قتلول يې شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5568, 'Joshua 8:22', 'Joshua', 8, 22, '&nbsp;نو د هغه ښار نه اِسرائيليان په جنګ کښې د شاملېدو دپاره ښکته راکوز شول. نو د عى سړى د بنى اِسرائيلو په مينځ کښې ګېر شوى وُو نو هغوئ ټول ووژلے شول. هيڅ څوک هم ونۀ تښتېدل او نۀ څوک ژوندى پاتې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5569, 'Joshua 8:23', 'Joshua', 8, 23, '&nbsp;صِرف د عى بادشاه ژوندے ګېر شو او يشوَع له بوتلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5570, 'Joshua 8:24', 'Joshua', 8, 24, '&nbsp;بنى اِسرائيلو هلته په صحرا کښې خپل ټول دشمنان وژل چرته چې ورپسې راغلى وُو. او بيا هغوئ عى ته واپس لاړل او هلته يې هم هر يو کس ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5571, 'Joshua 8:27', 'Joshua', 8, 27, '&nbsp;لکه څنګه چې مالِک خُدائ يشوَع ته فرمائيلى وُو بنى اِسرائيلو په ښار کښې مال او څاروى د خپلو ځانونو دپاره قبضه کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5572, 'Joshua 8:28', 'Joshua', 8, 28, '&nbsp;يشوَع عى وسوزولو او په کنډر يې بدل کړو او هغه تر نن ورځې پورې هم هغسې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5573, 'Joshua 8:29', 'Joshua', 8, 29, '&nbsp;هغۀ د عى بادشاه د يوې ونې سره پهانسى کړو او تر ماښامه پورې يې هلته پرېښودو. په ماښام کښې يشوَع حُکم وکړو چې د هغۀ لاش دې لرې کړے شى او د ښار دروازې سره دې وغورزولے شى. هغوئ هغه د کاڼو د غټ ډېرى لاندې پټ کړو کوم چې تر نن ورځې پورې هلته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5574, 'Joshua 8:30', 'Joshua', 8, 30, '&nbsp;بيا يشوَع مالِک خُدائ د بنى اِسرائيلو خُدائ پاک ته د عيبال په غرۀ باندې يوه قربان‌ګاه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5575, 'Joshua 8:31', 'Joshua', 8, 31, '&nbsp;هغه يې د هغه اصُولو په مطابق جوړه کړه چې د مالِک خُدائ خادِم موسىٰ بنى اِسرائيلو ته ښودلى وُو. لکه څنګه چې د موسىٰ د شريعت په کِتاب کښې ليکلى دى چې، ”قربان‌ګاه دې د داسې کاڼو نه جوړه وى چې د اوسپنې په آوزار تراشلے شوى نۀ وى.“ او په هغې باندې هغوئ مالِک خُدائ ته سوزېدونکې نذرانې او د سلامتۍ نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5576, 'Joshua 8:32', 'Joshua', 8, 32, '&nbsp;هلته د بنى اِسرائيلو په مخکښې يشوَع په کاڼو باندې د هغه شريعت يو نقل جوړ کړو کوم چې موسىٰ ليکلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5577, 'Joshua 8:33', 'Joshua', 8, 33, '&nbsp;اِسرائيليان سره د مشرانو، آفسرانو او قاضيانو او سره د هغه نورو قومونو چې د هغوئ سره اوسېدل د مالِک خُدائ د لوظ صندوق دواړو طرفونو ته ودرېدل. او ليويانو اِمامانو ته يې مخ وو چا چې د لوظ صندوق اوچت کړے وو. نيم خلق داسې ولاړ وُو چې شا يې د ګِرزيم غرۀ ته وه او د نيمو خلقو شا عيبال غرۀ ته وه. د مالِک خُدائ خِدمت کوونکى موسىٰ دوئ ته حُکم کړے وو چې کله ورباندې د برکت موندلو وخت راشى نو داسې دې وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5578, 'Joshua 8:34', 'Joshua', 8, 34, '&nbsp;بيا يشوَع هغه ټول شريعت ولوستو چې برکتونه او لعنتونه په کښې شامل وُو، هم هغه شان چې څنګه د شريعت په کِتاب کښې ليکلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5579, 'Joshua 8:35', 'Joshua', 8, 35, '&nbsp;هغه ټولې غونډې ته د يشوَع په ذريعه د موسىٰ هر يو حُکم واورولے شو چې په دې غونډه کښې ښځې، ماشومان او د نورو قومونو هغه خلق هم شامل وُو چې د هغوئ سره اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5580, 'Joshua 9:1', 'Joshua', 9, 1, '&nbsp;چې څۀ شوى وُو نو د اُردن نمرپرېواتۀ طرف ته ټول بادشاهان د هغې نه خبر شول. دا د حِتيانو، اموريانو، کنعانيانو، فرزيانو، حِويانو او يبوسيانو بادشاهان وُو، څوک چې د غرونو په مُلک کښې او د نمرپرېواتۀ په طرف د غرونو په لمنو کښې او د مديترانى د سمندر غاړې سره د شمال په طرف د لبنان غرونو پورې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5581, 'Joshua 9:2', 'Joshua', 9, 2, '&nbsp;هغوئ ټول يو ځائ شول او د يشوَع او بنى اِسرائيلو خِلاف يې فوجونه راغونډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5582, 'Joshua 9:3', 'Joshua', 9, 3, '&nbsp;چې يشوَع د يريحو او عى سره څۀ کړى وُو نو د جبعون خلق حِويان د هغې نه خبر شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5583, 'Joshua 9:4', 'Joshua', 9, 4, '&nbsp;نو هغوئ د هغۀ د دوکه کولو فېصله وکړه. هغوئ لاړل او څۀ خوراک يې راواخستو او زړې بوجۍ او بيا ګنډلے شوى د ميو مشکونه يې په خرونو باندې بار کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5584, 'Joshua 9:5', 'Joshua', 9, 5, '&nbsp;هغوئ زړې مخلے شوې جامې او مرمت شوې زړې څپلۍ واچولې. او هغه روټۍ چې هغوئ ځان سره اخستې وه، اوچه او پشمى شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5585, 'Joshua 9:6', 'Joshua', 9, 6, '&nbsp;بيا هغوئ هغه کېمپ ته ورغلل چې په جِلجال کښې وو او يشوَع او بنى اِسرائيلو ته يې ووئيل، ”مونږه د لرې مُلک نه راغلى يُو. مونږ غواړُو چې تاسو مونږ سره يوه معاهده وکړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5586, 'Joshua 9:7', 'Joshua', 9, 7, '&nbsp;خو بنى اِسرائيلو ووئيل، ”مونږ تاسو سره څنګه معاهده وکړُو؟ کېدے شى چې تاسو د نزدې ځائ اوسېدونکى يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5587, 'Joshua 9:8', 'Joshua', 9, 8, '&nbsp;هغوئ يشوَع ته ووئيل، ”مونږ ستاسو خِدمتګار يُو.“ يشوَع د هغوئ نه تپوس وکړو، ”تاسو څوک يئ؟ او د کوم ځائ نه راغلى يئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5588, 'Joshua 9:9', 'Joshua', 9, 9, '&nbsp;بيا هغوئ يشوَع ته دا قيصه بيان کړه، ”صاحِبه، مونږ د مالِک خُدائ ستاسو خُدائ پاک په حقله اورېدلى دى او مونږ د هغه هر څۀ نه خبر شوى يُو چې هغۀ په مِصر کښې کړى دى نو مونږ ځکه د ډېر لرى مُلک نه راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5589, 'Joshua 9:10', 'Joshua', 9, 10, '&nbsp;او څۀ چې هغۀ د اُردن نمرخاتۀ طرف ته د اموريانو دوو بادشاهانو سره کړى دى يعنې د حسبون بادشاه سيحون او د بسن بادشاه عوج سره چې هغه په عستارات کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5590, 'Joshua 9:11', 'Joshua', 9, 11, '&nbsp;زمونږ مشرانو او زمونږ په مُلک کښې اوسېدونکو ټولو خلقو مونږ ته ووئيل چې د سفر دپاره څۀ خوراک تيار کړُو او تاسو سره مِلاوېدو له راشو. مونږ ته وئيلے شوى وُو چې خپل ځانونه ستاسو خِدمت ته حاضر کړُو. او تاسو ته ووايو چې تاسو زمونږ سره يو تړون وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5591, 'Joshua 9:12', 'Joshua', 9, 12, '&nbsp;زمونږ روټۍ ته وګوره، کله چې مونږ د دې سره د خپلو کورونو نه ستاسو سره مِلاوېدو دپاره راوتُو نو دا لا ګرمه وه. خو وګوره، اوس دا اوچه شوې ده او پشم يې کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5592, 'Joshua 9:13', 'Joshua', 9, 13, '&nbsp;کله چې مونږ مشکونه د ميو نه ډک کړل نو دا نوى وُو. خو وګوره، اوس دا شلېدلى دى. زمونږه جامې او څپلۍ د اوږد سفر په وجه زړې شوې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5593, 'Joshua 9:14', 'Joshua', 9, 14, '&nbsp;بنى اِسرائيلو د هغوئ څۀ روټۍ واخستله، خو هغوئ د مالِک خُدائ سره د دې په حقله مشوره ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5594, 'Joshua 9:15', 'Joshua', 9, 15, '&nbsp;يشوَع د جبعون خلقو سره د امن تړون وکړو او هغوئ يې ژوندى پرېښودل. د بنى اِسرائيلو مشرانو کلکه وعده وکړه چې په معاهده باندې به عمل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5595, 'Joshua 9:16', 'Joshua', 9, 16, '&nbsp;د تړون نه درې ورځې وروستو بنى اِسرائيلو ته پته ولګېده چې دا خلق په حقيقت کښې د نزدې ځائ اوسېدونکى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5596, 'Joshua 9:17', 'Joshua', 9, 17, '&nbsp;نو اِسرائيليان روان شول او درې ورځې پس هغه ښارونو ته ورسېدل چې دا خلق په کښې اوسېدل، جبعون، کفيره، بيروت او قِريَت‌يعريم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5597, 'Joshua 9:18', 'Joshua', 9, 18, '&nbsp;خو بنى اِسرائيلو هغوئ ځکه نۀ شول وژلے چې د هغوئ مشرانو ورسره د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک په نامه کلکه وعده کړې وه. ټولو خلقو د دې په حقله مشرانو ته شکايت وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5598, 'Joshua 9:19', 'Joshua', 9, 19, '&nbsp;خو هغوئ په جواب کښې ووئيل، ”مونږه هغوئ سره د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک په نوم کلکه وعده کړې ده. اوس مونږ هغوئ ته څۀ نقصان نۀ شُو رسولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5599, 'Joshua 9:20', 'Joshua', 9, 20, '&nbsp;د خپلې وعدې په وجه په مونږ لازم دى چې هغوئ اوسېدو ته پرېږدو. کۀ مونږ داسې ونۀ کړل نو خُدائ پاک به مونږ له سزا راکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(5600, 'Joshua 9:21', 'Joshua', 9, 21, '&nbsp;هغوئ مۀ وژنئ خو هغوئ به زمونږ دپاره لرګى ماتوى او اوبۀ به راوړى.“ او مشرانو هم دغه مشوره راکړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');